import { useEffect, useState } from 'react'
import { NavLink, useLocation } from 'react-router-dom'
import {
    FiChevronDown,
    FiCompass,
    FiEdit3,
    FiFileText,
    FiHelpCircle,
    FiHome,
    FiList,
    FiLogIn,
    FiMail,
    FiMessageSquare,
    FiImage,
    FiPlusCircle,
    FiSettings,
    FiStar,
    FiTool,
    FiUserPlus,
    FiUsers,
    FiMenu,
    FiX,
} from 'react-icons/fi'

const getGroupFromPath = (path) => {
    if (path === '/admin') return 'home'
    if (path.startsWith('/admin/services')) return 'services'
    if (path.startsWith('/admin/bookings')) return 'booking'
    if (path.startsWith('/admin/reviews')) return 'reviews'
    if (path.startsWith('/admin/faq')) return 'faq'
    if (path.startsWith('/admin/tips-for-car')) return 'car-tips'
    if (path.startsWith('/admin/contact')) return 'contact'
    if (path.startsWith('/admin/banner')) return 'banner'
    if (path.startsWith('/admin/auth')) return 'auth-pages'
    return 'home'
}

function SideBar () {
    const [isMobileOpen, setIsMobileOpen] = useState(false)
    const { pathname } = useLocation()
    const [openGroup, setOpenGroup] = useState(getGroupFromPath(pathname))

    useEffect(() => {
        setOpenGroup(getGroupFromPath(pathname))
        setIsMobileOpen(false)
    }, [pathname])

    const groupClass = 'overflow-hidden rounded-2xl border border-gray-200 bg-white/95 shadow-sm'
    const summaryClass = 'flex w-full items-center justify-between gap-3 rounded-2xl px-4 py-3 text-left text-sm font-semibold transition'
    const navItemBaseClass = 'mx-1 flex items-center gap-2 rounded-xl px-4 py-2.5 text-sm font-medium transition'
    const navItemInactiveClass = 'text-gray-700 hover:bg-gray-100/80 hover:text-gray-900'
    const navItemActiveClass = 'bg-gradient-to-r from-red-50 to-rose-50 text-red-700 ring-1 ring-red-200 shadow-sm'

    const closeMobile = () => setIsMobileOpen(false)
    const toggleGroup = (groupKey) => setOpenGroup((prev) => (prev === groupKey ? null : groupKey))

    const navLinkClass = ({ isActive }) => `${navItemBaseClass} ${isActive ? navItemActiveClass : navItemInactiveClass}`

    const sections = [
        {
            key: 'home',
            label: 'Home',
            icon: FiHome,
            items: [
                { type: 'link', to: '/admin', end: true, icon: FiCompass, label: 'View Home' },
                { type: 'soon', icon: FiEdit3, label: 'Edit Home Content (coming soon)' },
            ],
        },
        {
            key: 'services',
            label: 'Services',
            icon: FiTool,
            items: [
                { type: 'link', to: '/admin/services/view', icon: FiList, label: 'View Services' },
                { type: 'link', to: '/admin/services/add', icon: FiPlusCircle, label: 'Add New Service' },
                { type: 'soon', icon: FiSettings, label: 'Manage Services (coming soon)' },
            ],
        },
        {
            key: 'booking',
            label: 'Booking',
            icon: FiFileText,
            items: [
                { type: 'link', to: '/admin/bookings/view', icon: FiList, label: 'View Booking' },
            ],
        },
        {
            key: 'reviews',
            label: 'Reviews',
            icon: FiStar,
            items: [
                { type: 'link', to: '/admin/reviews/view', icon: FiList, label: 'View Reviews' },
                { type: 'soon', icon: FiMessageSquare, label: 'Manage Feedback (coming soon)' },
            ],
        },
        {
            key: 'faq',
            label: 'FAQ',
            icon: FiHelpCircle,
            items: [
                { type: 'link', to: '/admin/faq/view', icon: FiFileText, label: 'View FAQs' },
                { type: 'link', to: '/admin/faq/add', icon: FiPlusCircle, label: 'Add New FAQ' },
            ],
        },
        {
            key: 'car-tips',
            label: 'Car Tips',
            icon: FiCompass,
            items: [
                { type: 'link', to: '/admin/tips-for-car/view', icon: FiList, label: 'View Car Tips' },
                { type: 'soon', icon: FiPlusCircle, label: 'Add New Tip (coming soon)' },
            ],
        },
        {
            key: 'contact',
            label: 'Contact',
            icon: FiMail,
            items: [
                { type: 'link', to: '/admin/contact/view', icon: FiCompass, label: 'View Contact Page' },
                { type: 'soon', icon: FiUsers, label: 'Manage Contact Requests (coming soon)' },
            ],
        },
        {
            key: 'banner',
            label: 'Banner',
            icon: FiImage,
            items: [
                { type: 'link', to: '/admin/banner/view', icon: FiList, label: 'View Banner' },
                { type: 'link', to: '/admin/banner/update', icon: FiEdit3, label: 'Update Banner' },
            ],
        },
        {
            key: 'auth-pages',
            label: 'Auth Pages',
            icon: FiLogIn,
            items: [
                { type: 'link', to: '/admin/auth/login-page', icon: FiLogIn, label: 'Login Page' },
                { type: 'link', to: '/admin/auth/register-page', icon: FiUserPlus, label: 'Register Page' },
            ],
        },
    ]

    const menuContent = (
        <>
            <div className='mb-4 rounded-xl border border-red-200 bg-red-50 px-4 py-3'>
                <p className='text-xs font-semibold uppercase tracking-wide text-red-700'>Admin Panel</p>
                <p className='mt-1 text-sm font-extrabold text-gray-900'>Website Navigation</p>
            </div>

            <div className='space-y-3'>
                {sections.map((section) => {
                    const SectionIcon = section.icon
                    const isOpen = openGroup === section.key

                    return (
                        <div key={section.key} className={groupClass}>
                            <button
                                type='button'
                                className={`${summaryClass} ${isOpen ? 'bg-gradient-to-r from-red-600 to-rose-600 text-white shadow-sm' : 'text-gray-800 hover:bg-gray-50'}`}
                                onClick={() => toggleGroup(section.key)}
                            >
                                <span className='inline-flex items-center gap-2'>
                                    <SectionIcon className={`h-4 w-4 ${isOpen ? 'text-white' : 'text-red-600'}`} />
                                    {section.label}
                                </span>
                                <FiChevronDown className={`h-4 w-4 transition ${isOpen ? 'rotate-180 text-white/90' : 'text-gray-500'}`} />
                            </button>

                            {isOpen && (
                                <div className='mt-3 space-y-2 px-3 pb-3'>
                                    {section.items.map((item) => {
                                        const ItemIcon = item.icon

                                        if (item.type === 'soon') {
                                            return (
                                                <button
                                                    key={item.label}
                                                    type='button'
                                                    disabled
                                                    className={`${navItemBaseClass} cursor-not-allowed text-gray-400`}
                                                >
                                                    <ItemIcon className='h-4 w-4 text-gray-400' />
                                                    {item.label}
                                                </button>
                                            )
                                        }

                                        return (
                                            <NavLink
                                                key={item.to}
                                                to={item.to}
                                                end={item.end}
                                                className={navLinkClass}
                                                onClick={closeMobile}
                                            >
                                                {({ isActive }) => (
                                                    <>
                                                        <ItemIcon className={`h-4 w-4 ${isActive ? 'text-red-600' : 'text-gray-500'}`} />
                                                        {item.label}
                                                    </>
                                                )}
                                            </NavLink>
                                        )
                                    })}
                                </div>
                            )}
                        </div>
                    )
                })}
            </div>
        </>
    )

    return (
        <div className='w-full'>
            <div className='mb-3 flex lg:hidden'>
                <button
                    type='button'
                    onClick={() => setIsMobileOpen(true)}
                    className='inline-flex items-center gap-2 rounded-lg border border-gray-200 bg-white px-4 py-2 text-sm font-semibold text-gray-800 shadow-sm transition hover:bg-gray-50'
                >
                    <FiMenu className='h-4 w-4 text-red-600' />
                    Open Menu
                </button>
            </div>

            {isMobileOpen && (
                <div className='fixed inset-0 z-[60] lg:hidden'>
                    <button
                        type='button'
                        aria-label='Close menu overlay'
                        onClick={closeMobile}
                        className='absolute inset-0 bg-black/40'
                    />

                    <aside className='absolute left-0 top-0 h-full w-[88vw] max-w-sm overflow-y-auto border-r border-gray-200 bg-gradient-to-b from-white to-gray-50 p-4 shadow-xl'>
                        <div className='mb-3 flex justify-end'>
                            <button
                                type='button'
                                onClick={closeMobile}
                                className='inline-flex items-center gap-2 rounded-lg border border-gray-200 bg-white px-3 py-2 text-xs font-semibold text-gray-700 shadow-sm transition hover:bg-gray-50'
                            >
                                <FiX className='h-4 w-4' />
                                Close
                            </button>
                        </div>

                        {menuContent}
                    </aside>
                </div>
            )}

            <aside className='hidden w-full max-w-sm rounded-2xl border border-gray-200 bg-gradient-to-b from-white to-gray-50 p-4 shadow-sm lg:sticky lg:top-4 lg:block lg:max-h-[calc(100dvh-2rem)] lg:overflow-y-auto'>
                {menuContent}
            </aside>
        </div>
    )
}

export default SideBar

import { useEffect, useMemo, useState } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { useNavigate } from 'react-router-dom'
import { FiCheckCircle, FiImage, FiUpload } from 'react-icons/fi'

import {
    createBanner,
    fetchLatestBanner,
    updateBanner,
} from '../../rtk/thunks/bannerThunk/bannerThunk'

function UpdateBanner () {
    const dispatch = useDispatch()
    const navigate = useNavigate()
    const { latestBanner, loading, error } = useSelector((state) => state.banner)

    const [form, setForm] = useState({
        title: '',
        description: '',
        link: '',
    })

    const [files, setFiles] = useState({
        imageOne: null,
        imageTwo: null,
        imageThree: null,
    })

    const [touched, setTouched] = useState({})
    const [submitError, setSubmitError] = useState('')
    const [successModal, setSuccessModal] = useState({
        open: false,
        message: '',
    })

    useEffect(() => {
        dispatch(fetchLatestBanner())
    }, [dispatch])

    useEffect(() => {
        if (!latestBanner) return

        setForm({
            title: latestBanner.title || '',
            description: latestBanner.description || '',
            link: latestBanner.link || '',
        })
    }, [latestBanner])

    const errors = useMemo(() => {
        const e = {}
        if (!form.title.trim()) e.title = 'Title is required'
        if (!form.description.trim()) e.description = 'Description is required'
        if (!form.link.trim()) e.link = 'Link is required'
        return e
    }, [form])

    const hasExistingImages = Boolean(
        latestBanner?.imageOne && latestBanner?.imageTwo && latestBanner?.imageThree,
    )

    const needsAllImages = !hasExistingImages

    const fileErrors = useMemo(() => {
        const e = {}

        if (needsAllImages) {
            if (!files.imageOne) e.imageOne = 'Image 1 is required'
            if (!files.imageTwo) e.imageTwo = 'Image 2 is required'
            if (!files.imageThree) e.imageThree = 'Image 3 is required'
        }

        return e
    }, [files, needsAllImages])

    const setField = (key, value) => setForm((prev) => ({ ...prev, [key]: value }))
    const setFile = (key, value) => setFiles((prev) => ({ ...prev, [key]: value }))
    const markTouched = (key) => setTouched((prev) => ({ ...prev, [key]: true }))

    const createPreview = (file, fallbackUrl = '') => {
        if (file) return URL.createObjectURL(file)
        return fallbackUrl
    }

    const onSubmit = async (e) => {
        e.preventDefault()
        setSubmitError('')
        setTouched({
            title: true,
            description: true,
            link: true,
            imageOne: true,
            imageTwo: true,
            imageThree: true,
        })

        if (Object.keys(errors).length > 0 || Object.keys(fileErrors).length > 0) return

        const payload = new FormData()
        payload.append('title', form.title.trim())
        payload.append('description', form.description.trim())
        payload.append('link', form.link.trim())

        if (files.imageOne) payload.append('imageOne', files.imageOne)
        if (files.imageTwo) payload.append('imageTwo', files.imageTwo)
        if (files.imageThree) payload.append('imageThree', files.imageThree)

        const isEditMode = Boolean(latestBanner?._id)

        try {
            if (isEditMode) {
                await dispatch(updateBanner({ bannerId: latestBanner._id, bannerData: payload })).unwrap()
            } else {
                await dispatch(createBanner(payload)).unwrap()
            }

            if (!isEditMode) {
                setForm({
                    title: '',
                    description: '',
                    link: '',
                })
                setFiles({ imageOne: null, imageTwo: null, imageThree: null })
                setTouched({})
            } else {
                await dispatch(fetchLatestBanner())
            }

            setSuccessModal({
                open: true,
                message: isEditMode ? 'Banner updated successfully.' : 'Banner created successfully.',
            })
        } catch (err) {
            const exactError = typeof err === 'string' ? err : (err?.message || 'Failed to save banner')
            setSubmitError(exactError)
        }
    }

    const errorMessage = typeof error === 'string' ? error : (error?.message || 'Failed to save banner')

    return (
        <section>
            {successModal.open && (
                <div className='fixed inset-0 z-[100] flex items-center justify-center bg-black/40 p-4'>
                    <div className='w-full max-w-md rounded-2xl border border-emerald-200 bg-white p-5 shadow-xl'>
                        <div className='flex items-start gap-3'>
                            <div className='rounded-full bg-emerald-100 p-2'>
                                <FiCheckCircle className='h-5 w-5 text-emerald-600' />
                            </div>
                            <div>
                                <h2 className='text-lg font-extrabold text-gray-900'>Success</h2>
                                <p className='mt-1 text-sm font-medium text-gray-700'>{successModal.message}</p>
                            </div>
                        </div>

                        <div className='mt-5 flex justify-end'>
                            <button
                                type='button'
                                onClick={() => {
                                    setSuccessModal({ open: false, message: '' })
                                    navigate('/admin/banner/view')
                                }}
                                className='inline-flex items-center rounded-md bg-red-600 px-4 py-2 text-sm font-semibold text-white transition hover:bg-red-700'
                            >
                                OK
                            </button>
                        </div>
                    </div>
                </div>
            )}

            <div className='mb-5 rounded-2xl border border-gray-200 bg-gradient-to-r from-white via-white to-red-50 p-4 shadow-sm sm:p-5'>
                <h1 className='text-2xl font-extrabold tracking-tight text-gray-900'>Update Banner</h1>
                <p className='mt-1 text-sm text-gray-600'>Upload banner images and update home banner content.</p>
            </div>

            <div className='rounded-2xl border border-gray-200 bg-white p-4 shadow-sm ring-1 ring-black/5 sm:p-6'>
                <form onSubmit={onSubmit} className='space-y-5'>
                    <label className='block'>
                        <span className='text-sm font-semibold text-gray-900'>Title</span>
                        <input
                            type='text'
                            value={form.title}
                            onChange={(e) => setField('title', e.target.value)}
                            onBlur={() => markTouched('title')}
                            placeholder='e.g. Professional Car Repair You Can Trust'
                            className='cr-input'
                        />
                        {touched.title && errors.title && <p className='mt-1 text-xs font-semibold text-red-600'>{errors.title}</p>}
                    </label>

                    <label className='block'>
                        <span className='text-sm font-semibold text-gray-900'>Description</span>
                        <textarea
                            rows={4}
                            value={form.description}
                            onChange={(e) => setField('description', e.target.value)}
                            onBlur={() => markTouched('description')}
                            placeholder='Describe your banner offer...'
                            className='cr-textarea'
                        />
                        {touched.description && errors.description && <p className='mt-1 text-xs font-semibold text-red-600'>{errors.description}</p>}
                    </label>

                    <label className='block'>
                        <span className='text-sm font-semibold text-gray-900'>CTA Link</span>
                        <input
                            type='text'
                            value={form.link}
                            onChange={(e) => setField('link', e.target.value)}
                            onBlur={() => markTouched('link')}
                            placeholder='e.g. /book-repair or https://example.com'
                            className='cr-input'
                        />
                        {touched.link && errors.link && <p className='mt-1 text-xs font-semibold text-red-600'>{errors.link}</p>}
                    </label>

                    <div className='grid gap-4 md:grid-cols-3'>
                        {[
                            { key: 'imageOne', label: 'Banner Image 1', existing: latestBanner?.imageOne },
                            { key: 'imageTwo', label: 'Banner Image 2', existing: latestBanner?.imageTwo },
                            { key: 'imageThree', label: 'Banner Image 3', existing: latestBanner?.imageThree },
                        ].map((imgField) => (
                            <div key={imgField.key} className='rounded-xl border border-gray-200 bg-gray-50 p-3'>
                                <p className='mb-2 text-sm font-semibold text-gray-900'>{imgField.label}</p>

                                <label className='inline-flex w-full cursor-pointer items-center justify-center gap-2 rounded-md border border-dashed border-gray-300 bg-white px-3 py-2 text-xs font-semibold text-gray-700 transition hover:border-red-300 hover:text-red-700'>
                                    <FiUpload className='h-4 w-4' />
                                    Upload Image
                                    <input
                                        type='file'
                                        accept='image/*'
                                        className='hidden'
                                        onChange={(e) => setFile(imgField.key, e.target.files?.[0] || null)}
                                        onBlur={() => markTouched(imgField.key)}
                                    />
                                </label>

                                {(files[imgField.key] || imgField.existing) && (
                                    <div className='mt-3 overflow-hidden rounded-lg border border-gray-200 bg-white'>
                                        <div className='aspect-[16/10] bg-gray-100'>
                                            <img
                                                src={createPreview(files[imgField.key], imgField.existing)}
                                                alt={imgField.label}
                                                className='h-full w-full object-cover'
                                            />
                                        </div>
                                        <p className='flex items-center gap-1 border-t border-gray-200 px-2 py-1 text-[11px] font-semibold text-gray-600'>
                                            <FiImage className='h-3.5 w-3.5 text-red-600' />
                                            {files[imgField.key]?.name || 'Existing image'}
                                        </p>
                                    </div>
                                )}

                                {touched[imgField.key] && fileErrors[imgField.key] && (
                                    <p className='mt-1 text-xs font-semibold text-red-600'>{fileErrors[imgField.key]}</p>
                                )}
                            </div>
                        ))}
                    </div>

                    <div className='flex flex-col gap-2'>
                        <button
                            type='submit'
                            className='inline-flex w-fit items-center gap-2 rounded-md bg-red-600 px-5 py-2.5 text-sm font-semibold text-white shadow-sm transition hover:bg-red-700 disabled:cursor-not-allowed disabled:opacity-60'
                            disabled={loading}
                        >
                            <FiUpload className='h-4 w-4' />
                            {loading ? 'Saving...' : latestBanner?._id ? 'Update Banner' : 'Create Banner'}
                        </button>

                        {(submitError || error) && (
                            <p className='text-sm font-semibold text-red-600'>
                                {submitError || errorMessage}
                            </p>
                        )}
                    </div>
                </form>
            </div>
        </section>
    )
}

export default UpdateBanner

import { useEffect, useState } from 'react'

import { AnimatePresence, motion } from 'framer-motion'
import { FiChevronDown, FiMenu, FiPhoneCall, FiUser, FiX } from 'react-icons/fi'
import { NavLink } from 'react-router-dom'
import { useDispatch, useSelector } from 'react-redux'

import { logout } from '../../rtk/slices/userSlice/userSlice'

function Navbar () {
    const [isOpen, setIsOpen] = useState(false)
    const [isProfileOpen, setIsProfileOpen] = useState(false)
    const [isExploreOpen, setIsExploreOpen] = useState(false)

    const dispatch = useDispatch()

    // Logged-in user (set by login + fetchCurrentUser thunk). If null => not logged in.
    const { user, loading } = useSelector((state) => state.user)

    const tokenRole = (() => {
        try {
            const token = localStorage.getItem('token')
            if (!token) return null

            const payloadBase64 = token.split('.')[1]
            if (!payloadBase64) return null

            const payload = JSON.parse(atob(payloadBase64))
            if (Array.isArray(payload?.roles)) return payload.roles
            return payload?.role || null
        } catch {
            return null
        }
    })()

    const hasToken = Boolean(localStorage.getItem('token'))
    const isAuthed = Boolean(user) || hasToken
    const isHydratingAuth = hasToken && !user && loading
    const isAdmin = String(user?.role || '').toLowerCase() === 'admin'
        || tokenRole === 'admin'
        || (Array.isArray(tokenRole) && tokenRole.includes('admin'))

    const navLinks = [
        { name: 'Home', to: '/' },
        { name: 'Services', to: '/services' },
        { name: 'Car Tips', to: '/tips-for-car' },
        { name: 'Book Repair', to: isAuthed ? '/book-repair' : '/login' },
        { name: 'Contact', to: '/contact' },
    ]

    const exploreLinks = [
        { name: 'Why Us', to: '/why-us' },
        { name: 'Reviews', to: '/reviews' },
        { name: 'FAQ', to: '/faq' },
    ]

    const authLinks = [
        { name: 'Login', to: '/login' },
        { name: 'Register', to: '/register' },
    ]

    const navItemClass = ({ isActive }) => (
        isActive
            ? 'text-sm font-semibold text-red-600'
            : 'text-sm font-medium text-gray-700 transition hover:text-red-600'
    )

    const handleLogout = () => {
        dispatch(logout())
        setIsProfileOpen(false)
        setIsOpen(false)
    }

    useEffect(() => {
        if (!isOpen) {
            document.body.style.overflow = ''
            return
        }

        document.body.style.overflow = 'hidden'

        return () => {
            document.body.style.overflow = ''
        }
    }, [isOpen])

    return (
        <header className='sticky top-0 z-50 border-b border-gray-200 bg-white/90 backdrop-blur'>
            <nav className='mx-auto flex max-w-7xl items-center justify-between px-4 py-3 sm:px-6 lg:px-8'>
                <NavLink to='/' className='flex items-center gap-2'>
                    <span className='rounded-md bg-red-600 px-2 py-1 text-sm font-bold text-white'>CR</span>
                    <span className='text-lg font-bold text-gray-900'>Car Repair Pro</span>
                </NavLink>

                <ul className='hidden items-center gap-8 md:flex'>
                    {navLinks.map((link) => (
                        <li key={link.name}>
                            <NavLink to={link.to} className={navItemClass}>
                                {link.name}
                            </NavLink>
                        </li>
                    ))}

                    <li
                        className='relative'
                        onMouseEnter={() => setIsExploreOpen(true)}
                        onMouseLeave={() => setIsExploreOpen(false)}
                    >
                        <button
                            type='button'
                            className='inline-flex items-center gap-1 text-sm font-medium text-gray-700 transition hover:text-red-600'
                            aria-haspopup='menu'
                            aria-expanded={isExploreOpen}
                        >
                            Explore
                            <FiChevronDown className={`h-4 w-4 transition ${isExploreOpen ? 'rotate-180 text-red-600' : 'text-gray-500'}`} />
                        </button>

                        <AnimatePresence>
                            {isExploreOpen && (
                                <motion.div
                                    key='explore-menu'
                                    initial={{ opacity: 0, y: -6 }}
                                    animate={{ opacity: 1, y: 0 }}
                                    exit={{ opacity: 0, y: -6 }}
                                    transition={{ duration: 0.16, ease: 'easeOut' }}
                                    className='absolute left-0 top-full z-20 mt-2 w-44 overflow-hidden rounded-md border border-gray-200 bg-white shadow-lg'
                                    role='menu'
                                >
                                    {exploreLinks.map((link) => (
                                        <NavLink
                                            key={link.name}
                                            to={link.to}
                                            className='block px-4 py-2 text-sm text-gray-700 transition hover:bg-gray-50 hover:text-red-600'
                                            role='menuitem'
                                            onClick={() => setIsExploreOpen(false)}
                                        >
                                            {link.name}
                                        </NavLink>
                                    ))}
                                </motion.div>
                            )}
                        </AnimatePresence>
                    </li>
                </ul>

                <div className='hidden items-center gap-3 md:flex'>
                    {!isAuthed && !isHydratingAuth ? (
                        <>
                            <NavLink to={authLinks[0].to} className={navItemClass}>
                                {authLinks[0].name}
                            </NavLink>
                            <NavLink
                                to={authLinks[1].to}
                                className={({ isActive }) => (
                                    isActive
                                        ? 'rounded-md border border-red-600 bg-red-50 px-4 py-2 text-sm font-semibold text-red-600'
                                        : 'rounded-md border border-red-600 px-4 py-2 text-sm font-semibold text-red-600 transition hover:bg-red-50'
                                )}
                            >
                                {authLinks[1].name}
                            </NavLink>
                        </>
                    ) : (
                        <div className='relative'>
                            <button
                                type='button'
                                onClick={() => setIsProfileOpen((prev) => !prev)}
                                className='inline-flex items-center gap-2 rounded-md border border-gray-200 bg-white px-3 py-2 text-sm font-semibold text-gray-800 transition hover:bg-gray-50'
                                aria-haspopup='menu'
                                aria-expanded={isProfileOpen}
                            >
                                <span className='inline-flex h-7 w-7 items-center justify-center rounded-full bg-gray-100 text-gray-700'>
                                    <FiUser className='h-4 w-4' aria-hidden='true' />
                                </span>
                                <span className='max-w-[140px] truncate'>{user?.name || (isHydratingAuth ? 'Loading...' : 'Account')}</span>
                            </button>

                            <AnimatePresence>
                                {isProfileOpen && (
                                    <motion.div
                                        key='profile-menu'
                                        initial={{ opacity: 0, y: -6 }}
                                        animate={{ opacity: 1, y: 0 }}
                                        exit={{ opacity: 0, y: -6 }}
                                        transition={{ duration: 0.15, ease: 'easeOut' }}
                                        className='absolute right-0 mt-2 w-48 overflow-hidden rounded-md border border-gray-200 bg-white shadow-lg'
                                        role='menu'
                                    >
                                        {!isAdmin ? (
                                            <>
                                                <NavLink
                                                    to='/my-appointments'
                                                    className='block px-4 py-2 text-sm text-gray-700 hover:bg-gray-50'
                                                    role='menuitem'
                                                    onClick={() => setIsProfileOpen(false)}
                                                >
                                                    My Appointments
                                                </NavLink>
                                                <NavLink
                                                    to='/profile'
                                                    className='block px-4 py-2 text-sm text-gray-700 hover:bg-gray-50'
                                                    role='menuitem'
                                                    onClick={() => setIsProfileOpen(false)}
                                                >
                                                    My Profile
                                                </NavLink>
                                            </>
                                        ) : (
                                            <NavLink
                                                to='/admin'
                                                className='block px-4 py-2 text-sm text-gray-700 hover:bg-gray-50'
                                                role='menuitem'
                                                onClick={() => setIsProfileOpen(false)}
                                            >
                                                Visit Admin Panel
                                            </NavLink>
                                        )}

                                        <button
                                            type='button'
                                            className='block w-full px-4 py-2 text-left text-sm font-semibold text-red-600 hover:bg-red-50'
                                            role='menuitem'
                                            onClick={handleLogout}
                                        >
                                            Logout
                                        </button>
                                    </motion.div>
                                )}
                            </AnimatePresence>
                        </div>
                    )}

                    <a
                        href='tel:+923001234567'
                        className='rounded-md bg-red-600 px-4 py-2 text-sm font-semibold text-white transition hover:bg-red-700'
                    >
                        <span className='inline-flex items-center gap-2'>
                            <FiPhoneCall className='h-4 w-4' aria-hidden='true' />
                            Call Now
                        </span>
                    </a>
                </div>

                <button
                    type='button'
                    className='inline-flex items-center justify-center rounded-md p-2 text-gray-700 hover:bg-gray-100 md:hidden'
                    aria-label='Toggle menu'
                    onClick={() => {
                        setIsOpen((prev) => !prev)
                        setIsProfileOpen(false)
                    }}
                >
                    {isOpen ? <FiX className='h-6 w-6' aria-hidden='true' /> : <FiMenu className='h-6 w-6' aria-hidden='true' />}
                </button>
            </nav>

            <AnimatePresence initial={false}>
                {isOpen && (
                    <motion.div
                        key='mobile-menu'
                        className='absolute left-0 right-0 top-full max-h-[calc(100dvh-4.5rem)] overflow-y-auto overscroll-contain border-t border-gray-200 bg-white px-4 pb-4 pt-2 shadow-lg md:hidden'
                        initial={{ opacity: 0, y: -8 }}
                        animate={{ opacity: 1, y: 0 }}
                        exit={{ opacity: 0, y: -8 }}
                        transition={{ duration: 0.18, ease: 'easeOut' }}
                    >
                        <ul className='space-y-2'>
                            {navLinks.map((link) => (
                                <li key={link.name}>
                                    <NavLink
                                        to={link.to}
                                        className={({ isActive }) => (
                                            isActive
                                                ? 'block rounded-md bg-red-50 px-3 py-2 text-sm font-semibold text-red-700'
                                                : 'block rounded-md px-3 py-2 text-sm font-medium text-gray-700 hover:bg-gray-100 hover:text-red-600'
                                        )}
                                        onClick={() => setIsOpen(false)}
                                    >
                                        {link.name}
                                    </NavLink>
                                </li>
                            ))}

                            <li className='rounded-md border border-gray-200 bg-gray-50/60 p-2'>
                                <p className='px-2 py-1 text-xs font-bold uppercase tracking-wide text-gray-500'>Explore</p>
                                <div className='mt-1 space-y-1'>
                                    {exploreLinks.map((link) => (
                                        <NavLink
                                            key={link.name}
                                            to={link.to}
                                            className={({ isActive }) => (
                                                isActive
                                                    ? 'block rounded-md bg-red-50 px-3 py-2 text-sm font-semibold text-red-700'
                                                    : 'block rounded-md px-3 py-2 text-sm font-medium text-gray-700 hover:bg-gray-100 hover:text-red-600'
                                            )}
                                            onClick={() => setIsOpen(false)}
                                        >
                                            {link.name}
                                        </NavLink>
                                    ))}
                                </div>
                            </li>
                        </ul>

                        <div className='mt-3 grid gap-2'>
                            {!isAuthed && !isHydratingAuth ? (
                                <>
                                    <NavLink
                                        to={authLinks[0].to}
                                        className='inline-flex w-full items-center justify-center rounded-md border border-gray-200 bg-white px-4 py-2 text-sm font-semibold text-gray-800 transition hover:bg-gray-50'
                                        onClick={() => setIsOpen(false)}
                                    >
                                        {authLinks[0].name}
                                    </NavLink>
                                    <NavLink
                                        to={authLinks[1].to}
                                        className='inline-flex w-full items-center justify-center rounded-md border border-red-600 bg-white px-4 py-2 text-sm font-semibold text-red-600 transition hover:bg-red-50'
                                        onClick={() => setIsOpen(false)}
                                    >
                                        {authLinks[1].name}
                                    </NavLink>
                                </>
                            ) : (
                                <>
                                    {!isAdmin ? (
                                        <>
                                            <NavLink
                                                to='/my-appointments'
                                                className='inline-flex w-full items-center justify-center rounded-md border border-gray-200 bg-white px-4 py-2 text-sm font-semibold text-gray-800 transition hover:bg-gray-50'
                                                onClick={() => setIsOpen(false)}
                                            >
                                                My Appointments
                                            </NavLink>
                                            <NavLink
                                                to='/profile'
                                                className='inline-flex w-full items-center justify-center rounded-md border border-gray-200 bg-white px-4 py-2 text-sm font-semibold text-gray-800 transition hover:bg-gray-50'
                                                onClick={() => setIsOpen(false)}
                                            >
                                                My Profile
                                            </NavLink>
                                        </>
                                    ) : (
                                        <NavLink
                                            to='/admin'
                                            className='inline-flex w-full items-center justify-center rounded-md border border-gray-200 bg-white px-4 py-2 text-sm font-semibold text-gray-800 transition hover:bg-gray-50'
                                            onClick={() => setIsOpen(false)}
                                        >
                                            Visit Admin Panel
                                        </NavLink>
                                    )}

                                    <button
                                        type='button'
                                        className='inline-flex w-full items-center justify-center rounded-md border border-red-600 bg-white px-4 py-2 text-sm font-semibold text-red-600 transition hover:bg-red-50'
                                        onClick={handleLogout}
                                    >
                                        Logout
                                    </button>
                                </>
                            )}
                            <a
                                href='tel:+923001234567'
                                className='inline-flex w-full items-center justify-center rounded-md bg-red-600 px-4 py-2 text-sm font-semibold text-white transition hover:bg-red-700'
                            >
                                Emergency Call
                            </a>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </header>
    )
}

export default Navbar

